const axios = require('axios');

const baseUrl = env.get('AXET_AI_BASE_URL');
const model = env.get('AXET_AI_MODEL');
const apiKey = env.get('AXET_AI_API_KEY') || '';

if (!baseUrl || !model) {
  throw new Error('AXET_AI_BASE_URL and AXET_AI_MODEL are required');
}

const maxTokensRaw = Number(msg.payload.max_tokens ?? env.get('AI_MAX_TOKENS'));
const maxTokens = Number.isFinite(maxTokensRaw) && maxTokensRaw > 0 ? maxTokensRaw : 800;
const temperatureRaw = Number(msg.payload.temperature ?? env.get('AI_TEMPERATURE'));
const temperature = Number.isFinite(temperatureRaw) && temperatureRaw >= 0 ? temperatureRaw : 0.2;

const system = String(msg.payload.system || '');
const user = String(msg.payload.user || '');

const messages = system
  ? [{ role: 'system', content: system }, { role: 'user', content: user }]
  : [{ role: 'user', content: user }];

const headers = { 'Content-Type': 'application/json' };
if (apiKey) {
  headers.Authorization = `Bearer ${apiKey}`;
}

function extractJson(text) {
  if (!text) return null;
  const raw = String(text).trim();
  if (!raw) return null;

  try {
    return JSON.parse(raw);
  } catch (error) {}

  const codeFenceRegex = /```(?:json)?\s*([\s\S]*?)```/gi;
  for (const match of raw.matchAll(codeFenceRegex)) {
    const snippet = String(match?.[1] || '').trim();
    if (!snippet) continue;
    try {
      return JSON.parse(snippet);
    } catch (error) {}
  }

  const firstObj = raw.indexOf('{');
  const firstArr = raw.indexOf('[');
  let start = -1;
  let open = '';
  let close = '';
  if (firstObj !== -1 && (firstArr === -1 || firstObj < firstArr)) {
    start = firstObj;
    open = '{';
    close = '}';
  } else if (firstArr !== -1) {
    start = firstArr;
    open = '[';
    close = ']';
  } else {
    return null;
  }

  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < raw.length; i += 1) {
    const ch = raw[i];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (ch === '\\') {
      escaped = true;
      continue;
    }
    if (ch === '"') {
      inString = !inString;
      continue;
    }
    if (inString) {
      continue;
    }
    if (ch === open) {
      depth += 1;
    } else if (ch === close) {
      depth -= 1;
      if (depth === 0) {
        const snippet = raw.slice(start, i + 1);
        try {
          return JSON.parse(snippet);
        } catch (error) {
          return null;
        }
      }
    }
  }

  return null;
}

const payload = {
  model,
  temperature,
  max_tokens: maxTokens,
  messages,
  response_format: { type: 'json_object' },
};

let response;
try {
  response = await axios.post(`${baseUrl.replace(/\/+$/, '')}/chat/completions`, payload, { headers });
} catch (error) {
  const message = JSON.stringify(error?.response?.data || {}) || error.message || '';
  if (error?.response?.status === 400 && String(message).toLowerCase().includes('response_format')) {
    const fallback = { ...payload };
    delete fallback.response_format;
    response = await axios.post(`${baseUrl.replace(/\/+$/, '')}/chat/completions`, fallback, { headers });
  } else {
    throw error;
  }
}

const content = response?.data?.choices?.[0]?.message?.content || '';
let parsed = null;
try {
  parsed = JSON.parse(content);
} catch (error) {
  parsed = extractJson(content);
}

if (!parsed) {
  throw new Error('AI response was not valid JSON');
}

msg.payload = { result: parsed, raw: content };
return msg;

const axios = require('axios');

const baseUrl = env.get('AXET_AI_BASE_URL');
const model = env.get('AXET_AI_MODEL');
const apiKey = env.get('AXET_AI_API_KEY') || '';

if (!baseUrl || !model) {
  throw new Error('AXET_AI_BASE_URL and AXET_AI_MODEL are required');
}

const maxTokensRaw = Number(msg.payload.max_tokens ?? env.get('AI_MAX_TOKENS'));
const maxTokens = Number.isFinite(maxTokensRaw) && maxTokensRaw > 0 ? maxTokensRaw : 800;
const temperatureRaw = Number(msg.payload.temperature ?? env.get('AI_TEMPERATURE'));
const temperature = Number.isFinite(temperatureRaw) && temperatureRaw >= 0 ? temperatureRaw : 0.4;

const system = String(msg.payload.system || '');
const safeMessages = Array.isArray(msg.payload.messages) ? msg.payload.messages : [];
const chatMessages = system
  ? [{ role: 'system', content: system }, ...safeMessages]
  : safeMessages.length ? safeMessages : [{ role: 'user', content: String(msg.payload.user || '') }];

const headers = { 'Content-Type': 'application/json' };
if (apiKey) {
  headers.Authorization = `Bearer ${apiKey}`;
}

const payload = {
  model,
  temperature,
  max_tokens: maxTokens,
  messages: chatMessages,
};

const response = await axios.post(`${baseUrl.replace(/\/+$/, '')}/chat/completions`, payload, { headers });
const content = response?.data?.choices?.[0]?.message?.content || '';

msg.payload = { answer: content };
return msg;

